        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if all digits
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric: compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                if num1 > num2:
                    return 1
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare by ASCII
                if id1 < id2:
                    return -1
                if id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        if len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(v):
        major, minor, patch, prerelease = parse_version(v)
        # Return tuple for sorting
        # For pre-release: (0, identifiers) if has pre-release, (1,) if not
        # This ensures versions without pre-release sort after those with
        if prerelease:
            pre_tuple = (0, prerelease)
        else:
            pre_tuple = (1,)
        return (major, minor, patch, pre_tuple)

